//! Review adapter only: no oracle expected arithmetic.
use lp1_node::{fixed::U256,rewards::{shares,split,ShareInput,Route},hex};
use serde_json::{json,Value};
use std::io::{self,BufRead};
fn main() {for l in io::stdin().lock().lines(){let v:Value=serde_json::from_str(&l.unwrap()).unwrap();let p=U256::from_dec_str(v["pot"].as_str().unwrap()).unwrap();let s=split(&p,v["alpha"].as_u64().unwrap() as u16,v["gamma"].as_u64().unwrap() as u16).unwrap();let counts:Vec<_>=v["counts"].as_array().unwrap().iter().map(|r|ShareInput{id:hex::decode(r[0].as_str().unwrap()).unwrap().try_into().unwrap(),count:r[1].as_u64().unwrap() as u16,tomb:r[2].as_bool().unwrap(),account_exists:r[3].as_bool().unwrap()}).collect();let r=shares(&s.remainder,&counts,v["kappa"].as_u64().unwrap() as u8,v["m"].as_u64().unwrap() as u16).unwrap();println!("{}",json!({"winner":s.winner.to_dec_string(),"proposer":s.proposer.to_dec_string(),"remainder":s.remainder.to_dec_string(),"amount":r.amount.to_dec_string(),"baseBurn":r.base_burn.to_dec_string(),"roundBurn":r.round_burn.to_dec_string(),"paid":r.paid.to_dec_string(),"penaltyBurn":r.penalty_burn.to_dec_string(),"payBurn":r.pay_burn.to_dec_string(),"payments":r.payments.iter().map(|(id,n,route)|json!({"id":hex::encode(id),"amount":n.to_dec_string(),"route":match route{Route::Paid=>"paid",Route::PenaltyBurn=>"penaltyBurn",Route::PayBurn=>"payBurn"}})).collect::<Vec<_>>()}));}}
